using System;using System.IO;using System.Linq;
namespace Ara {public static class SatisfactionPolicyTests {
 static void Yes(bool value,string text){if(!value)throw new Exception(text);}
 static State New(){var s=State.New();var d=s.GetDay(new DateTime(2026,10,21));d.Wake=d.Wake.Date.AddHours(8);GridEngine.Ensure(s,d);d.Records.Add(new CellBlock{Id="morning",Start=d.Wake,Count=6,Category="작업",Satisfaction=4});d.Records.Add(new CellBlock{Id="future",Start=d.Wake.AddHours(4),Count=3,Category="작업",Satisfaction=0});return s;}
 public static void Run(Action<string,Action> check,string dir){
  check("satisfaction policy: elapsed only and partial slot",()=>{var s=New();var d=s.Days[0];var sleep=Adaptive.Target(s,d);var a=SatisfactionPolicy.Calculate(s,d,sleep,d.Wake.AddHours(1));Yes(a.Average==4&&a.Minutes==60,"future excluded");a=SatisfactionPolicy.Calculate(s,d,sleep,d.Wake.AddMinutes(65));Yes(a.Average==250m/65&&a.Minutes==65,"partial minute weighting");a=SatisfactionPolicy.Calculate(s,d,sleep,d.Wake.AddMinutes(-5));Yes(a.Minutes==0,"before wake");});
  check("satisfaction policy: blank zero and exclusion",()=>{var s=New();var d=s.Days[0];var sleep=Adaptive.Target(s,d);s.BlankSatisfactionValue=0;var a=SatisfactionPolicy.Calculate(s,d,sleep,d.Wake.AddMinutes(90));Yes(a.Average==240m/90,"zero is not missing");s.ExcludeBlankSatisfaction=true;a=SatisfactionPolicy.Calculate(s,d,sleep,d.Wake.AddMinutes(90));Yes(a.Average==4&&a.Minutes==60,"exclude denominator");d.Records.Clear();Yes(SatisfactionPolicy.Calculate(s,d,sleep,d.Wake.AddMinutes(90)).Minutes==0,"no records no score");});
  check("satisfaction policy: settings persist and independent devices merge",()=>{var s=New();var b=ReplicaSync.Slice(s,s.Days[0].Date);var local=Store.Clone(b);local.BlankSatisfactionValue=5;local.ExcludeBlankSatisfaction=true;var remote=Store.Clone(b);remote.Days[0].Note="메모";var merged=ReplicaSync.Merge(b,local,remote,b.Days[0].Date);var path=Path.Combine(dir,"satisfaction-policy.json");new Store(path).Save(merged);var loaded=new Store(path).Load();Yes(loaded.BlankSatisfaction==5&&loaded.ExcludeBlankSatisfaction&&loaded.Days[0].Note=="메모","settings and other changes retained");});
  check("wake confirmation: midnight selection and new day",()=>{var s=State.New();var d=s.GetDay(new DateTime(2026,10,21));GridEngine.Ensure(s,d);Yes(!SatisfactionPolicy.WakeConfirmed(d),"new day unconfirmed");PhoneEditing.Apply(s,d,new PhoneCommand{op="wake",lane=1,first=0,last=0});Yes(SatisfactionPolicy.WakeConfirmed(d)&&d.Wake.Hour==0,"midnight can be selected");Yes(!SatisfactionPolicy.WakeConfirmed(s.GetDay(d.Wake.AddDays(1))),"next day unconfirmed");});
  check("satisfaction policy: legacy defaults, past day and validation",()=>{var s=New();var d=s.Days[0];Yes(s.BlankSatisfaction==2,"legacy default two");d.WakeConfirmed=null;Yes(SatisfactionPolicy.WakeConfirmed(d),"legacy record day");var sleep=Adaptive.Target(s,d);Yes(SatisfactionPolicy.Calculate(s,d,sleep,sleep.AddDays(1)).Finish==sleep,"past cap");s.BlankSatisfactionValue=6;bool rejected=false;try{Engine.Validate(s);}catch(InvalidDataException){rejected=true;}Yes(rejected,"out of range");});
 }
}}
